algorithms.pseudocode:
function REACHES-BAD-BOUNDED(f, x, bad, card):
    cur <- x
    for n in 0 .. card:
        if cur in bad: return n          # first witness, n <= card
        cur <- f(cur)
    return NONE                          # forever safe

function MAXIMAL-SAFE-INVARIANT(f, universe, bad):
    survivors <- empty set;  N <- |universe|
    for x in universe \ bad:
        cur <- x;  ok <- true
        for _ in 0 .. N:
            if cur in bad: ok <- false; break
            cur <- f(cur)
        if ok: survivors <- survivors + {x}
    return survivors                     # largest forward-invariant safe set
